edits.oldText:
return Selector<PlaybackController, String?>(
          selector: (_, player) => player.songInfo?.track.path,
          builder: (context, playingPath, _) {
            // B-015: show the jump glyph when the playing track lives outside
            // the browsed folder; B-031 debounces the hide.
            final divergent =
                playingPath != null &&
                playingPath.isNotEmpty &&
                p.dirname(playingPath) != (path ?? '');
            final showJumpGlyph = resolveJumpGlyphVisible(divergent);
            // 12-px vertical padding preserves the crumb baseline; the 44×44
            // glyph hit target sits outside it (Material min, B-013).
            return Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(20, 12, 0, 12),
                    child: MidEllipsis(
                      text: path == null || path.isEmpty ? '~' : path,
                      style: mono(palette.fgSecondary, typography.crumbSize),
                    ),
                  ),
                ),
                if (showJumpGlyph && playingPath != null)
                  buildJumpGlyph(playingPath)
                else
                  const SizedBox(width: 20),
              ],
            );
          },
        );

edits.newText:
return Selector<PlaybackController, ({String? playingPath, bool isPlaying})>(
          selector: (_, player) => (
            playingPath: player.songInfo?.track.path,
            isPlaying: player.isPlaying,
          ),
          builder: (context, data, _) {
            final playingPath = data.playingPath;
            final playingActive =
                data.isPlaying && playingPath != null && playingPath.isNotEmpty;

            // B-015: show the jump glyph when the playing track lives outside
            // the browsed folder; B-031 debounces the hide.
            final divergent = playingActive &&
                p.dirname(playingPath!) != (path ?? '');
            final showJumpGlyph = playingActive
                ? resolveJumpGlyphVisible(divergent)
                : false;

            // Linux-only accessibility affordance: when the playing track
            // is already in the current folder but its row is not in view,
            // provide a semantics button to scroll it into view.
            final showLinuxInViewAction =
                playingActive &&
                Theme.of(context).platform == TargetPlatform.linux &&
                path != null &&
                p.dirname(playingPath!) == path &&
                libCtrl.tracks.any((t) => t.path == playingPath) &&
                !browserController.isTrackVisible(playingPath!);

            // 12-px vertical padding preserves the crumb baseline; the 44×44
            // glyph hit target sits outside it (Material min, B-013).
            return Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(20, 12, 0, 12),
                    child: MidEllipsis(
                      text: path == null || path.isEmpty ? '~' : path,
                      style: mono(palette.fgSecondary, typography.crumbSize),
                    ),
                  ),
                ),
                if (showJumpGlyph && playingPath != null)
                  buildJumpGlyph(playingPath)
                else if (showLinuxInViewAction)
                  glyphButton(
                    semanticsLabel: 'show now-playing track in browser',
                    buttonKey:
                        const ValueKey('void-crumb-show-playing-row'),
                    onTap: () => jumpToNowPlaying(playingPath!),
                    box: 44,
                    glyph: '⊙',
                    style:
                        mono(palette.fgPrimary, typography.rowSize, height: 1),
                  )
                else
                  const SizedBox(width: 20),
              ],
            );
          },
        );

